app.use(helmet());
```

---

### **4. Rate Limiting**
Prevent abuse and brute-force attacks with rate limiting.

```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
});

app.use(limiter);
```

---

### **5. Use Environment Variables**
Avoid hardcoding ports and sensitive data.
Use environment variables (e.g., `process.env.PORT`).

```js
require('dotenv').config(); // Load env from .env file
const port = process.env.PORT || 3000;

app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});
```

---

### **6. Proper Error Handling Middleware**
Global error middleware to catch uncaught exceptions and validation/formatting errors.

```js
// At the end of app.js
