  console.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});

// Handle 404
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});
```

---

### **7. CORS Configuration**
Disable or restrict Cross-Origin Resource Sharing in production.

```js
const cors = require('cors');
app.use(cors({
  origin: true,
  credentials: true,
  methods: ['GET'], // or ['GET', 'POST'] as needed
}));
```

---

### **8. Sanitize Logs**
Never log sensitive data (e.g., passwords, tokens).

```js
// Filter sensitive data from logs
app.use((req, res, next) => {
  if (req.body.password) req.body.password = '[REDACTED]';
  next();
});
```

---

### **9. Sanitize Output**
Prevent XSS by sanitizing dynamic responses.

```js
const escapeHtml = require('escape-html');

// In route handlers:
res.json({
  data: {
    message: escapeHtml(req.query.message),
  },
});
```

---

### **10. Remove Trailing Stack Traces in Production**
In production, avoid sending stack traces in responses.

```js
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1); // Graceful shutdown
});
```

