   - Avoid exposing sensitive error details in production.

### 3. **Security Best Practices**
   - Use Helmet to set secure HTTP headers.
   - Avoid exposing stack traces in error responses.
   - Validate all inputs to prevent injection attacks.

### 4. **Logging**
   - Use a logging library like `winston` or `morgan` to log request details and errors.

### 5. **Rate Limiting**
   - Implement rate limiting to prevent abuse.

### 6. **Environment Variables**
   - Use environment variables for configuration (e.g., port, API keys).

### Improved Code

```javascript
const express = require('express');
const { body, validationResult, query } = require('express-validator');
const helmet = require('helmet');
const winston = require('winston');
const rateLimit = require('express-rate-limit');
const app = express();

// Initialize winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.Console()],
});

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Health check endpoint
app.get('/health', (req, res) => {
  logger.info('Health check endpoint called');
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation
app.get('/users',
  query('id').optional().isInt().withMessage('ID must be an integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Invalid query parameter', { errors: errors.array() });
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const userId = req.query.id;
    if (userId) {
      const user = users.find(u => u.id === parseInt(userId));
      if (!user) {
        logger.info('User not found', { userId });
        return res.status(404).json({ error: 'User not found' });
      }
      res.json(user);
    } else {
      res.json(users);
    }
  }
);

// Centralized error handling middleware
app.use((err, req, res, next) => {
  logger.error('Error occurred', { error: err.message, stack: err.stack });
  res.status(500).json({ error: 'Internal server error' });
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

### Key Improvements:
1. **Helmet**: Secures the app by setting various HTTP headers.
2. **Express-Validator**: Validates and sanitizes input data.
3. **Winston**: Logs requests and errors.
4. **Rate Limiting**: Prevents abuse by limiting the number of requests.
5. **Error Handling Middleware**: Centralizes error handling and logging.
6. **Environment Variables**: Uses `process.env.PORT` for configuration.

### Additional Steps:
- Install the required dependencies:
  ```bash
  npm install express express-validator helmet winston express-rate-limit
  ```

- Use environment variables for sensitive configuration values.

These changes will make your app more secure and robust.
